"""Original chapter practice. Correct option is first in source; shuffled on export."""
import random
import re
SETS = {1: [], 2: []}
def rows(set_no, ch, text):
    for line in text.strip().splitlines():
        def readable(s):
            s=re.sub(r'([ก-๙])([A-Za-z0-9])',r'\1 \2',s)
            return re.sub(r'([A-Za-z0-9_%])([ก-๙])',r'\1 \2',s)
        topic, stem, correct, b, c, d, why = map(readable,line.split(' | '))
        options = [correct, b, c, d]
        random.Random(f'quick-{set_no}-{ch}-{topic}').shuffle(options)
        SETS[set_no].append(dict(ch=ch, topic=topic, stem=stem, options=options,
                                 answer=options.index(correct), why=why))

