if __name__ == '__main__':
    from collections import Counter
    for number, questions in SETS.items():
        assert Counter(q['ch'] for q in questions) == {ch:15 for ch in range(7,13)}
        assert len({q['stem'] for q in questions}) == 90
        for q in questions:
            assert len(q['options']) == len(set(q['options'])) == 4
            assert 0 <= q['answer'] < 4 and q['why'] and q['topic']
    assert len({q['stem'] for qs in SETS.values() for q in qs}) == 180
    print('PASS: 2 sets, 90 questions/set, 15/chapter, unique stems and valid explanations')
